  const key=region+':'+role,valid=new Set(pool);let bag=Array.isArray(store[key])?store[key].filter(x=>valid.has(x)):[];
  if(!bag.length){bag=pool.slice();for(let i=bag.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]]}
   const last=store[key+':last'];if(bag.length>1&&bag[bag.length-1]===last)[bag[0],bag[bag.length-1]]=[bag[bag.length-1],bag[0]]}
